-- Payroll, step 4 of docs/HR-PLAN.md: local holidays by town, each person's work town, and HR's
-- own payroll register uploaded and compared with the CRM's month.

-- Who added or archived a national holiday (never deleted: archived), and its proclamation.
alter table holiday
  add column proclamation text,
  add column made_by bigint references person (id),
  add column made_at timestamptz,
  add column archived_by bigint references person (id),
  add column archived_at timestamptz,
  add column archive_note text;
--> statement-breakpoint
-- A holiday of one province (town null) or one city or municipality only. Names are the CRM's town
-- list's (apps/web/public/places/ph-towns.json, PSGC). A person's own holidays are the national
-- ones plus those of their work town and its province (hr/holidays.ts); the company's calendar
-- (desks' clocks) stays on the national ones. One row a day a place; made_by null: from the
-- 2026 proclamations below.
create table local_holiday (
  id bigint generated always as identity primary key,
  day date not null,
  name text not null,
  kind text not null default 'special' check (kind in ('regular', 'special')),
  province text not null,
  town text,
  proclamation text,
  made_by bigint references person (id),
  made_at timestamptz not null default now(),
  active boolean not null default true,
  archived_by bigint references person (id),
  archived_at timestamptz,
  archive_note text
);
--> statement-breakpoint
create unique index local_holiday_once on local_holiday (day, lower(province), lower(coalesce(town, ''))) where active;
--> statement-breakpoint
create index local_holiday_day on local_holiday (day) where active;
--> statement-breakpoint
-- Where a person works, for their local holidays: a town of the CRM's list and its province.
alter table employee
  add column work_town text,
  add column work_province text,
  add constraint employee_work_town check ((work_town is null) = (work_province is null));
--> statement-breakpoint
-- HR's own payroll register, uploaded for a month to compare with the CRM's. The mapping says
-- which heading holds what; HR makes it once and it is used again (the newest is in force).
create table pay_register_map (
  id bigint generated always as identity primary key,
  -- The sheet's name and the row its headings are on, as last used.
  sheet text not null,
  header_row integer not null check (header_row between 1 and 200),
  -- { code, name, basic, ot, gross, deductions, sss, philhealth, pagibig, tax, net }: a heading each, or null.
  columns jsonb not null,
  made_by bigint not null references person (id),
  made_at timestamptz not null default now()
);
--> statement-breakpoint
create table pay_register (
  id bigint generated always as identity primary key,
  month text not null check (month ~ '^\d{4}-\d{2}$'),
  file_name text not null,
  file_mime text not null,
  file_size integer not null,
  file_data bytea,
  file_key text,
  made_by bigint not null references person (id),
  made_at timestamptz not null default now(),
  constraint pay_register_has_bytes check (file_data is not null or file_key is not null)
);
--> statement-breakpoint
create index pay_register_month on pay_register (month, id);
--> statement-breakpoint
-- A row of a register matched to a person by name, confirmed by HR (an employee ID match needs none).
create table pay_register_match (
  id bigint generated always as identity primary key,
  register_id bigint not null references pay_register (id),
  row_number integer not null,
  person_id bigint not null references person (id),
  confirmed_by bigint not null references person (id),
  confirmed_at timestamptz not null default now(),
  unique (register_id, row_number)
);
--> statement-breakpoint
-- Each comparison of a register with the CRM's month, kept (the newest is the one shown).
create table pay_register_compare (
  id bigint generated always as identity primary key,
  register_id bigint not null references pay_register (id),
  map_id bigint not null references pay_register_map (id),
  -- released: the CRM's frozen payslips; draft: the month as it stood then.
  crm_status text not null check (crm_status in ('released', 'draft')),
  result jsonb not null,
  differences integer not null check (differences >= 0),
  made_by bigint not null references person (id),
  made_at timestamptz not null default now()
);
--> statement-breakpoint
create index pay_register_compare_register on pay_register_compare (register_id, id);
--> statement-breakpoint
-- The local special (non-working) days proclaimed for 2026, from Lawphil as HR's portal
-- (Automated-Excel lib/data/proclamations2026.js) keeps them: a region's become its provinces, a
-- list of towns one row each; a day that is a national holiday already is left out.

on conflict do nothing;
